import AppKit
import ApplicationServices
import Carbon.HIToolbox

/// Watches the system clipboard and saves each new copy.
final class ClipboardMonitor {
    private let db: Database
    private var timer: Timer?
    private var lastChangeCount = NSPasteboard.general.changeCount
    var onNewClip: ((Int64) -> Void)?

    /// Markers apps put on the clipboard to ask clipboard managers not to keep the contents (nspasteboard.org).
    private static let ignoredTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword", "de.petermaurer.TransientPasteboardType",
    ]
    private static let maxClipBytes = 30 * 1024 * 1024

    init(db: Database) { self.db = db }

    func start() {
        let t = Timer(timeInterval: 0.4, repeats: true) { [weak self] _ in self?.poll() }
        RunLoop.main.add(t, forMode: .common)
        timer = t
    }

    /// Call after writing to the clipboard ourselves, so the write is not saved as a new copy.
    func skipCurrentContents() { lastChangeCount = NSPasteboard.general.changeCount }

    private func poll() {
        let pb = NSPasteboard.general
        guard pb.changeCount != lastChangeCount else { return }
        lastChangeCount = pb.changeCount
        guard S.connected else { return }
        capture(pb)
    }

    private func capture(_ pb: NSPasteboard) {
        let types = Set((pb.types ?? []).map(\.rawValue))
        guard types.isDisjoint(with: Self.ignoredTypes) else { return }

        var formats: [ClipFormat] = []
        var text = ""
        var hashSource: Data?

        if S.saveFiles,
           let urls = pb.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL], !urls.isEmpty {
            text = urls.map(\.path).joined(separator: "\n")
            formats.append(ClipFormat(type: ClipFormat.files, data: Data(text.utf8)))
            hashSource = Data(("files:" + text).utf8)
        } else {
            if S.saveText, let s = pb.string(forType: .string), !s.isEmpty {
                text = s
                formats.append(ClipFormat(type: ClipFormat.text, data: Data(s.utf8)))
                hashSource = Data(s.utf8)
            }
            if S.saveRTF, let d = pb.data(forType: .rtf) { formats.append(ClipFormat(type: ClipFormat.rtf, data: d)) }
            if S.saveHTML, let d = pb.data(forType: .html) { formats.append(ClipFormat(type: ClipFormat.html, data: d)) }
            if S.saveImages, let png = Self.pngData(from: pb) {
                formats.append(ClipFormat(type: ClipFormat.png, data: png))
                if text.isEmpty {
                    let size = NSBitmapImageRep(data: png).map { "\($0.pixelsWide) x \($0.pixelsHigh)" } ?? ""
                    text = "Image \(size)"
                    hashSource = png
                }
            }
        }

        guard let hashSource, formats.contains(where: { $0.type != ClipFormat.rtf && $0.type != ClipFormat.html }) else { return }
        guard formats.reduce(0, { $0 + $1.data.count }) <= Self.maxClipBytes else { return }

        let id = db.addClip(text: text, formats: formats, crc: Database.crc(hashSource))
        db.trim(maxEntries: S.maxEntriesEnabled ? S.maxEntries : nil, expireDays: S.expireEnabled ? S.expireDays : nil)
        onNewClip?(id)
    }

    private static func pngData(from pb: NSPasteboard) -> Data? {
        if let d = pb.data(forType: .png) { return d }
        guard let tiff = pb.data(forType: .tiff), let rep = NSBitmapImageRep(data: tiff) else { return nil }
        return rep.representation(using: .png, properties: [:])
    }
}

enum Paster {
    /// Puts clips back on the clipboard. One untouched clip keeps every saved format; anything else becomes plain text.
    static func load(_ clips: [Clip], db: Database, plainText: Bool, transform: ((String) -> String)?) -> Bool {
        let pb = NSPasteboard.general
        if clips.count == 1, !plainText, transform == nil {
            let formats = db.formats(clips[0].id)
            guard !formats.isEmpty else { return false }
            pb.clearContents()
            if let files = formats.first(where: { $0.type == ClipFormat.files }), let paths = String(data: files.data, encoding: .utf8) {
                let urls = paths.split(separator: "\n").map { NSURL(fileURLWithPath: String($0)) }
                return pb.writeObjects(urls)
            }
            pb.declareTypes(formats.map { NSPasteboard.PasteboardType($0.type) }, owner: nil)
            for f in formats { pb.setData(f.data, forType: NSPasteboard.PasteboardType(f.type)) }
            return true
        }
        var text = clips.map { db.fullText($0.id) }.joined(separator: "\n")
        if let transform { text = transform(text) }
        pb.clearContents()
        return pb.setString(text, forType: .string)
    }

    static var canSendKeys: Bool { AXIsProcessTrusted() }

    /// Sends Cmd+V to the frontmost app. Needs the Accessibility permission.
    static func sendPaste() {
        let source = CGEventSource(stateID: .combinedSessionState)
        for down in [true, false] {
            let event = CGEvent(keyboardEventSource: source, virtualKey: CGKeyCode(kVK_ANSI_V), keyDown: down)
            event?.flags = .maskCommand
            event?.post(tap: .cghidEventTap)
        }
    }

    static func requestAccessibility() {
        let options = ["AXTrustedCheckOptionPrompt": true] as CFDictionary
        _ = AXIsProcessTrustedWithOptions(options)
    }

    /// Screen rectangle (Cocoa coordinates) of the text caret in the focused app, when it exposes one.
    static func caretRect() -> NSRect? {
        guard AXIsProcessTrusted() else { return nil }
        let system = AXUIElementCreateSystemWide()
        AXUIElementSetMessagingTimeout(system, 0.25)
        var focused: CFTypeRef?
        guard AXUIElementCopyAttributeValue(system, kAXFocusedUIElementAttribute as CFString, &focused) == .success,
              let focused, CFGetTypeID(focused) == AXUIElementGetTypeID() else { return nil }
        let element = focused as! AXUIElement
        var range: CFTypeRef?
        guard AXUIElementCopyAttributeValue(element, kAXSelectedTextRangeAttribute as CFString, &range) == .success, let range else { return nil }
        var bounds: CFTypeRef?
        guard AXUIElementCopyParameterizedAttributeValue(element, kAXBoundsForRangeParameterizedAttribute as CFString, range, &bounds) == .success,
              let bounds, CFGetTypeID(bounds) == AXValueGetTypeID() else { return nil }
        var rect = CGRect.zero
        guard AXValueGetValue(bounds as! AXValue, .cgRect, &rect), rect.height > 0, rect.origin != .zero else { return nil }
        let primaryHeight = NSScreen.screens.first?.frame.height ?? 0
        return NSRect(x: rect.minX, y: primaryHeight - rect.maxY, width: rect.width, height: rect.height)
    }
}

/// Ditto's "Paste Special" text conversions.
enum TextTransform {
    static func sentenceCase(_ s: String) -> String {
        var out = ""
        var capitalizeNext = true
        for ch in s.lowercased() {
            if capitalizeNext, ch.isLetter {
                out += String(ch).uppercased()
                capitalizeNext = false
            } else {
                out.append(ch)
            }
            if ".!?\n".contains(ch) { capitalizeNext = true }
        }
        return out
    }

    static func removeLineFeeds(_ s: String) -> String {
        s.replacingOccurrences(of: "\r\n", with: " ").replacingOccurrences(of: "\n", with: " ").replacingOccurrences(of: "\r", with: " ")
    }

    static func typoglycemia(_ s: String) -> String {
        var out = ""
        var word: [Character] = []
        func flush() {
            if word.count > 3 {
                let middle = word[1..<(word.count - 1)].shuffled()
                out += String([word[0]] + middle + [word[word.count - 1]])
            } else {
                out += String(word)
            }
            word.removeAll()
        }
        for ch in s {
            if ch.isLetter { word.append(ch) } else { flush(); out.append(ch) }
        }
        flush()
        return out
    }

    private static func words(_ s: String) -> [String] {
        s.components(separatedBy: CharacterSet.alphanumerics.inverted).filter { !$0.isEmpty }
    }

    static func camelCase(_ s: String) -> String {
        words(s).enumerated().map { $0.offset == 0 ? $0.element.lowercased() : $0.element.capitalized }.joined()
    }

    static func slugify(_ s: String) -> String {
        let folded = s.folding(options: [.diacriticInsensitive, .caseInsensitive], locale: nil)
        return words(folded).joined(separator: "-").lowercased()
    }

    static func addCurrentTime(_ s: String) -> String {
        let f = DateFormatter()
        f.dateStyle = .short
        f.timeStyle = .medium
        return s + " " + f.string(from: Date())
    }
}
